//! The Bluetooth source's WinRT bindings (`src/bluetooth/windows/bindings.rs`)
//! are generated by windows-bindgen from the filter beside them and checked
//! in, in its minimal style (classes deref to their default interface, other
//! interfaces are cast to, strings are `&str` and `String`) and flat: its
//! module layout leaves the minimal style's private delegate box out of
//! reach of the modules that use it. This regenerates them and fails when
//! the checked-in file differs;
//! `LYR_BLESS_BINDINGS=1` writes the regenerated file over it instead.

#![cfg(windows)]

use std::fs;
use std::path::Path;

#[test]
fn the_checked_in_bluetooth_bindings_are_what_the_filter_generates() {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("src/bluetooth/windows");
    let checked_in = dir.join("bindings.rs");
    let fresh = Path::new(env!("CARGO_TARGET_TMPDIR")).join("bluetooth_bindings.rs");
    windows_bindgen::builder()
        .output(&fresh)
        .filter_file(dir.join("bindings.txt"))
        .minimal()
        .flat()
        .write();
    let generated = fs::read_to_string(&fresh).expect("windows-bindgen wrote its output");
    if std::env::var_os("LYR_BLESS_BINDINGS").is_some() {
        fs::write(&checked_in, &generated).expect("the bindings are writable");
        return;
    }
    let kept = fs::read_to_string(&checked_in).expect("the bindings are checked in");
    assert!(
        kept == generated,
        "{} is stale: regenerate it with \
         `LYR_BLESS_BINDINGS=1 cargo test -p lyr-sources --test windows_bindings`",
        checked_in.display()
    );
}
